/// Tekst in de taal van de app; {naam}-plekken invullen via [v].
String ft(BuildContext c, String k, [Map<String, Object>? v]) {
  final l = Provider.of<I18n>(c, listen: false).locale;
  var s = kFotograaf[k]?[l] ?? kFotograaf[k]?['nl'] ?? k;
  v?.forEach((a, b) => s = s.replaceAll('{$a}', '$b'));
  return s;
}

